"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/questionnaire/variants/01-guided-questions";
const variants={"guided-questions":View0};
export interface ArtemisQuestionnaireProps { className?: string; variant?: "guided-questions"; }
export function ArtemisQuestionnaire({className,variant="guided-questions"}:ArtemisQuestionnaireProps) {const View=variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}

"use client";
// @zeus-internal
import { Check, CornerDownLeft, ArrowLeft } from "lucide-react";
import { motion } from "motion/react";
import { useEffect, useId, useRef, useState } from "react";
import type { FormEvent, KeyboardEvent } from "react";
import { ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
interface Option {
    value: string;
    label: string;
    hint: string;
}
interface Question {
    name: string;
    title: string;
    required: boolean;
    kind: "radio" | "text";
    options: Option[];
    label?: string;
    placeholder?: string;
}
const QUESTIONS: Question[] = [
    {
        name: "task",
        title: "What would you like to work on?",
        required: false,
        kind: "radio",
        options: [
            { value: "build", label: "Build something new", hint: "Turn an idea into a first version" },
            { value: "fix", label: "Fix a problem", hint: "Find what\u2019s wrong and put it right" },
            { value: "polish", label: "Polish what\u2019s there", hint: "Improve the details and interactions" },
            { value: "explore", label: "Explore an idea", hint: "Compare a few directions before building" },
        ],
    },
    {
        name: "starting-point",
        title: "Where should I start?",
        required: true,
        kind: "radio",
        options: [
            { value: "plan", label: "Make a plan", hint: "Walk me through the approach first" },
            { value: "draft", label: "Show me a draft", hint: "Give me something I can react to" },
            { value: "begin", label: "Get started", hint: "Work through it and share the result" },
        ],
    },
    {
        name: "details",
        title: "Any details I should know?",
        required: false,
        kind: "text",
        options: [],
        label: "Project details",
        placeholder: "A reference, a constraint, or something to avoid\u2026",
    },
];
const ROW = "art:group art:relative art:flex art:min-h-10 art:cursor-pointer art:items-center art:gap-2 art:rounded-xl art:px-3 art:py-2 art:text-sm art:outline-none art:transition-colors art:data-disabled:pointer-events-none art:data-disabled:opacity-50 art:hover:bg-foreground/5 art:has-[:focus-visible]:ring-2 art:has-[:focus-visible]:ring-ring";
const BTN_BACK = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:gap-2 art:px-3 art:text-sm art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:disabled:opacity-50 art:data-hidden:hidden art:mr-auto art:rounded-full";
const BTN_SKIP = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:gap-2 art:px-3 art:text-sm art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:disabled:opacity-50 art:data-hidden:hidden art:rounded-full";
const BTN_CONTINUE = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:gap-2 art:px-3 art:text-sm art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:disabled:opacity-50 art:data-hidden:hidden art:rounded-full";
const BTN_SEND = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:gap-2 art:px-3 art:text-sm art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:disabled:opacity-50 art:data-hidden:hidden art:rounded-full";
const EASE = [0.22, 1, 0.36, 1] as const;
const PRESS = { whileHover: { scale: 1.01 }, whileTap: { scale: 0.99 }, transition: ARTEMIS_SPRING_PRESS } as const;
const BTN_AGAIN = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-transparent art:text-foreground art:hover:bg-primary/5 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:mt-5 art:h-9 art:rounded-full";
type Status = "answered" | "unanswered" | "skipped";
export default function QuestionnaireGuidedQuestions() {
    const [session, setSession] = useState(0);
    const [done, setDone] = useState<number | null>(null);
    if (done !== null) {
        return (<div className="art:flex art:w-full art:items-center art:justify-center">
        <div className="art:w-full art:max-w-xl art:rounded-2xl art:border art:border-border art:bg-background art:p-5">
          <div className="art:flex art:items-center art:gap-2 art:text-sm">
            <Check className="art:size-4" aria-hidden="true"/>
            {"All set"}
          </div>
          <p className="art:mt-2 art:text-sm art:text-muted-foreground">{`${done} ${done === 1 ? "answer" : "answers"} noted for the next step.`}</p>
          <motion.button {...PRESS} type="button" tabIndex={0} className={BTN_AGAIN} onClick={() => {
                setSession((n) => n + 1);
                setDone(null);
            }}>
            {"Start again"}
          </motion.button>
        </div>
      </div>);
    }
    return <GuidedForm key={session} onDone={setDone}/>;
}
function GuidedForm({ onDone }: {
    onDone: (count: number) => void;
}) {
    const uid = useId();
    const [current, setCurrent] = useState(0);
    const [answers, setAnswers] = useState<Record<string, string>>({});
    const [skipped, setSkipped] = useState<Record<string, boolean>>({});
    const [invalid, setInvalid] = useState(false);
    const fieldsets = useRef<Array<HTMLFieldSetElement | null>>([]);
    const mounted = useRef(false);
    const total = QUESTIONS.length;
    const q = QUESTIONS[current];
    const isFirst = current === 0;
    const isLast = current === total - 1;
    const statusOf = (question: Question): Status => skipped[question.name] ? "skipped" : (answers[question.name] ?? "").trim() ? "answered" : "unanswered";
    const status = statusOf(q);
    useEffect(() => {
        if (!mounted.current) {
            mounted.current = true;
            return;
        }
        fieldsets.current[current]?.focus();
    }, [current]);
    const setAnswer = (name: string, value: string) => {
        setAnswers((prev) => ({ ...prev, [name]: value }));
        setSkipped((prev) => ({ ...prev, [name]: false }));
        setInvalid(false);
    };
    const go = (index: number) => {
        setInvalid(false);
        setCurrent(Math.min(Math.max(index, 0), total - 1));
    };
    const flagInvalid = () => {
        setInvalid(true);
        const first = fieldsets.current[current]?.querySelector("input");
        first?.focus();
    };
    const advance = () => {
        if (status === "unanswered") {
            flagInvalid();
            return;
        }
        if (!isLast)
            go(current + 1);
    };
    const answeredCount = (next: Record<string, string>, nextSkipped: Record<string, boolean>) => QUESTIONS.filter((question) => !nextSkipped[question.name] && (next[question.name] ?? "").trim()).length;
    const skip = () => {
        const nextSkipped = { ...skipped, [q.name]: true };
        const next = { ...answers, [q.name]: "" };
        if (isLast) {
            onDone(answeredCount(next, nextSkipped));
            return;
        }
        setSkipped(nextSkipped);
        setAnswers(next);
        go(current + 1);
    };
    const onSubmit = (event: FormEvent<HTMLFormElement>) => {
        event.preventDefault();
        if (status === "unanswered") {
            flagInvalid();
            return;
        }
        onDone(answeredCount(answers, skipped));
    };
    const focusOption = (index: number) => {
        const inputs = fieldsets.current[current]?.querySelectorAll<HTMLInputElement>("input[type=radio]");
        inputs?.[index]?.focus();
    };
    const onKeyDown = (event: KeyboardEvent<HTMLFormElement>) => {
        const target = event.target as HTMLElement;
        const inText = target instanceof HTMLInputElement && target.type === "text";
        const onRadio = target instanceof HTMLInputElement && target.type === "radio";
        if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) {
            event.preventDefault();
            if (isLast)
                event.currentTarget.requestSubmit();
            else
                advance();
            return;
        }
        if (target instanceof HTMLButtonElement)
            return;
        if (event.key === "Enter") {
            event.preventDefault();
            if (isLast)
                event.currentTarget.requestSubmit();
            else
                advance();
            return;
        }
        if (inText || event.altKey || event.metaKey || event.ctrlKey)
            return;
        if (q.kind === "radio" && /^[1-9]$/.test(event.key)) {
            const option = q.options[Number(event.key) - 1];
            if (option) {
                event.preventDefault();
                setAnswer(q.name, option.value);
                focusOption(Number(event.key) - 1);
            }
        }
        else if (onRadio) {
            return;
        }
        else if (q.kind === "radio" && (event.key === "ArrowDown" || event.key === "ArrowUp")) {
            event.preventDefault();
            const checked = q.options.findIndex((option) => option.value === answers[q.name]);
            const index = checked >= 0 ? checked : event.key === "ArrowDown" ? 0 : q.options.length - 1;
            if (checked < 0)
                setAnswer(q.name, q.options[index].value);
            focusOption(index);
        }
        else if (event.key === "ArrowLeft" && !isFirst) {
            event.preventDefault();
            go(current - 1);
        }
        else if (event.key === "ArrowRight" && status !== "unanswered" && !isLast) {
            event.preventDefault();
            go(current + 1);
        }
    };
    const visibility = (visible: boolean) => visible
        ? { "data-visible": "", tabIndex: 0 }
        : { "data-hidden": "", "aria-hidden": true, hidden: true, inert: true, tabIndex: -1 };
    const primary = (visible: boolean) => (visible ? { "data-shortcut": "Enter", "aria-keyshortcuts": "Enter" } : {});
    return (<div className="art:flex art:w-full art:items-center art:justify-center">
      <form data-current={current + 1} {...(isFirst ? { "data-first": "" } : {})} {...(isLast ? { "data-last": "" } : {})} data-total={total} data-shortcuts="numbers" noValidate aria-label="Plan your next task" onSubmit={onSubmit} onKeyDown={onKeyDown} className="art:w-full art:max-w-xl art:rounded-2xl art:border art:border-border art:bg-background art:p-2 art:text-foreground">
        <div data-current={current + 1} {...(isFirst ? { "data-first": "" } : {})} {...(isLast ? { "data-last": "" } : {})} data-total={total} aria-label="Questionnaire progress" aria-live="polite" aria-valuemax={total} aria-valuemin={1} aria-valuenow={current + 1} aria-valuetext={`Question ${current + 1} of ${total}`} role="progressbar" className="art:px-3 art:pt-2 art:text-xs art:text-muted-foreground">
          {`Question ${current + 1} of ${total}`}
        </div>
        {QUESTIONS.map((question, index) => {
            const active = index === current;
            const qStatus = statusOf(question);
            const showError = active && invalid;
            const errorId = `${uid}-err-${index}`;
            const canNext = qStatus !== "unanswered";
            const keys = [
                "Meta+Enter Control+Enter ArrowUp ArrowDown",
                !isFirst ? "ArrowLeft" : "",
                canNext && !isLast ? "ArrowRight" : "",
            ]
                .filter(Boolean)
                .join(" ");
            return (<motion.fieldset key={question.name} ref={(el) => {
                    fieldsets.current[index] = el;
                }} {...(question.required ? { "data-required": "" } : {})} {...(active ? { "data-active": "" } : { hidden: true, inert: true })} data-status={qStatus} {...(active ? { "aria-keyshortcuts": keys } : {})} {...(showError ? { "data-invalid": "", "aria-describedby": errorId, "aria-invalid": true } : {})} tabIndex={-1} initial={false} animate={active ? { opacity: 1, x: 0 } : { opacity: 0, x: 10 }} transition={{ x: { duration: 0.2, ease: EASE }, opacity: { duration: 0, delay: 0.2 } }} className="art:min-w-0 art:border-0 art:p-0 art:outline-none">
              <legend className="art:mb-2 art:w-full art:px-3 art:pt-2 art:text-xl art:font-medium">{question.title}</legend>
              <div data-shortcuts="numbers" className="art:space-y-1">
                {question.kind === "radio" ? (question.options.map((option, i) => {
                    const checked = answers[question.name] === option.value;
                    const state = checked ? { "data-checked": "" } : { "data-unchecked": "" };
                    const labelId = `${uid}-${index}-${i}-label`;
                    return (<div key={option.value} {...state} data-shortcut={i + 1} data-type="radio" className={ROW}>
                        {checked ? (<motion.span aria-hidden="true" className="art:absolute art:inset-0 art:rounded-xl art:bg-foreground/7" initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.15 }}/>) : null}
                        <input {...state} data-shortcut={i + 1} data-type="radio" aria-keyshortcuts={checked ? `${i + 1} Enter` : `${i + 1}`} type="radio" name={question.name} value={option.value} required={question.required} checked={checked} aria-labelledby={labelId} {...(showError ? { "aria-invalid": true } : {})} onChange={() => setAnswer(question.name, option.value)} className="art:absolute art:inset-0 art:z-20 art:size-full art:cursor-pointer art:opacity-0"/>
                        <span id={labelId} className="art:relative art:z-10 art:min-w-0 art:flex-1 art:leading-5">
                          <span className="art:font-medium">{option.label}</span>{" "}
                          <span className="art:text-muted-foreground">{option.hint}</span>
                        </span>
                        <span aria-hidden="true" className="art:relative art:z-10 art:grid art:size-6 art:shrink-0 art:place-items-center art:rounded-lg art:border art:border-border art:text-xs art:tabular-nums art:text-muted-foreground">
                          {checked ? (<motion.span initial={{ opacity: 0, scale: 0.5 }} animate={{ opacity: 1, scale: 1 }} transition={{ duration: 0.15 }}>
                              <Check className="art:size-3.5" aria-hidden="true"/>
                            </motion.span>) : (<span data-shortcut={i + 1} aria-hidden="true">
                              {i + 1}
                            </span>)}
                        </span>
                      </div>);
                })) : (<div className="art:px-3">
                    <input {...((answers[question.name] ?? "") === "" ? { "data-empty": "" } : {})} form="" type="text" aria-label={question.label} placeholder={question.placeholder} value={answers[question.name] ?? ""} onChange={(event) => setAnswer(question.name, event.target.value)} {...(showError ? { "data-invalid": "", "aria-invalid": true } : {})} className="art:my-2 art:h-10 art:w-full art:rounded-full art:border art:border-border art:bg-transparent art:px-4 art:text-sm art:outline-none art:placeholder:text-muted-foreground art:focus-visible:ring-2 art:focus-visible:ring-ring"/>
                  </div>)}
              </div>
              <p id={errorId} hidden={!showError} {...(showError ? { "data-invalid": "", role: "alert" } : {})} className="art:mt-3 art:px-3 art:text-sm art:text-destructive art:@min-[640px]/artemis:px-4">
                {question.required ? "Choose an answer to continue." : "Choose an answer or skip this question."}
              </p>
            </motion.fieldset>);
        })}
        <div className="art:mt-3 art:flex art:items-center art:justify-end art:gap-2 art:px-1 art:pb-1">
          <motion.button {...PRESS} type="button" data-status={status} {...visibility(!isFirst)} onClick={() => go(current - 1)} className={BTN_BACK}>
            <ArrowLeft className="art:size-4" aria-hidden="true"/>
            Back
          </motion.button>
          <motion.button {...PRESS} type="button" data-status={status} {...visibility(!q.required)} onClick={skip} className={BTN_SKIP}>
            Skip
          </motion.button>
          <motion.button {...PRESS} type="button" data-status={status} {...primary(!isLast)} {...visibility(!isLast)} onClick={advance} className={BTN_CONTINUE}>
            Continue
            <kbd aria-hidden="true" className="art:flex art:items-center art:rounded-md art:border art:border-current/15 art:px-1.5 art:py-0.5 art:text-xs">
              <CornerDownLeft className="art:size-3" aria-hidden="true"/>
            </kbd>
          </motion.button>
          <motion.button {...PRESS} type="submit" data-status={status} {...primary(isLast)} {...visibility(isLast)} className={BTN_SEND}>
            Send answers
            <kbd aria-hidden="true" className="art:flex art:items-center art:rounded-md art:border art:border-current/15 art:px-1.5 art:py-0.5 art:text-xs">
              <CornerDownLeft className="art:size-3" aria-hidden="true"/>
            </kbd>
          </motion.button>
        </div>
      </form>
    </div>);
}
